/**
 * P155: browse and compare REAL fetched, Git-blob-SHA verified MIT Rocketbox
 * assets. These are licensed FULLY CLOTHED reference humans, not replacements
 * for an owner's photographed clothes. Proof requires real WebGL in both
 * Chromium and WebKit at 320/390/430px and actual screenshot/image hashing.
 *
 * No external model requests from browsers: tiny local-only server; no
 * customer photos; no production/staging; no screenshot generated by AI.
 */
import {createServer} from 'node:http';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {resolve,extname} from 'node:path';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
import {chromium,webkit} from 'playwright';
import sharp from 'sharp';
import {FOUNDATION155,CANDIDATES155,chooseFoundation155}
 from '../research/dual-human-foundation-candidate-155/foundation-manifest.mjs';
import {inspectPinnedCandidate155}
 from '../research/dual-human-foundation-candidate-155/inspect-gltf.mjs';

const dir='benchmark/dual-human-foundation-candidate-155',
 engine=process.env.P155_ENGINE||'chromium',
 choices=['front','side','back','face'],widths=[320,390,430],
 browserFactory=engine==='chromium'?chromium:engine==='webkit'?webkit:null;
if(!browserFactory)throw Error('P155 only actual Chromium and WebKit sources supported');
const sha=b=>createHash('sha256').update(b).digest('hex');
const supported=new Map([
 ['/lab','research/dual-human-foundation-candidate-155/licensed-visual-lab.html'],
 ['/assets/ananya.glb',dir+'/assets/ananya.glb'],
 ['/assets/aarav.glb',dir+'/assets/aarav.glb']
]);
async function response(req,res){
 try{
  let pathname=new URL(req.url,'http://localhost').pathname;
  let filepath=supported.get(pathname);
  if(!filepath&&pathname.startsWith('/vendor/three/')){
   const tail=pathname.slice('/vendor/three/'.length);
   if(!/^(build\/three\.(?:module|core)\.js|examples\/jsm\/[a-zA-Z0-9_./-]+\.js)$/.test(tail)||
    tail.includes('..'))throw Error('P155 disallowed external JS');
   filepath='node_modules/three/'+tail;
  }
  if(!filepath)throw Error('P155 denied unknown local request');
  const bytes=await readFile(resolve(filepath));
  const type=extname(filepath)==='.html'?'text/html; charset=utf-8':
   extname(filepath)==='.js'?'text/javascript; charset=utf-8':
   extname(filepath)==='.glb'?'model/gltf-binary':'application/octet-stream';
  res.writeHead(200,{'Content-Type':type,'X-Content-Type-Options':'nosniff',
   'Cache-Control':'no-store','Access-Control-Allow-Origin':'none'});
  res.end(bytes);
 }catch(e){res.writeHead(404);res.end('P155 inaccessible non-approved local asset');}
}
const info=[];
for(const c of CANDIDATES155){
 const original=await readFile(resolve(dir+'/assets/'+c.file));
 const verified=inspectPinnedCandidate155(original,c);
 info.push(verified);
 if(chooseFoundation155({figure:c.key,previewOptIn:true,
  sourceManifestAuthenticated:true,ownerPhotoItemCount:1}).model!==
  'original-163-bone-photographed-outfit')
  throw Error('P155 account photograph gateway must block new dressed model');
}
const server=createServer(response);
await new Promise(ok=>server.listen(0,'127.0.0.1',ok));
const origin='http://127.0.0.1:'+server.address().port;
const evidence=[],problems=[];
let browser=null;
try{
 browser=await browserFactory.launch({headless:true,args:engine==='chromium'?
 ['--use-gl=angle','--use-angle=swiftshader','--enable-webgl','--disable-web-security']:[]});
 for(const width of widths){
  const context=await browser.newContext({
   viewport:{width,height:800},deviceScaleFactor:1,
   locale:'en-US',colorScheme:'light',
   reducedMotion:'reduce',serviceWorkers:'block'
  });
  for(const candidate of CANDIDATES155)for(const view of choices){
   const page=await context.newPage(),errors=[],failures=[],requests=[];
   page.on('pageerror',e=>errors.push(e.message));
   page.on('console',e=>{if(e.type()==='error')errors.push(e.text());});
   page.on('requestfailed',r=>failures.push(r.url()+' '+r.failure()?.errorText));
   page.on('request',r=>{if(!r.url().startsWith(origin)&&!r.url().startsWith('blob:'+origin)&&!r.url().startsWith('data:'))requests.push(r.url());});
   try{
    await page.goto(origin+'/lab?figure='+candidate.key+'&view='+view,
     {waitUntil:'domcontentloaded',timeout:45000});
    await page.waitForFunction(()=>{
     const s=window.__cc155Status?.();
     return (s?.loaded&&s.frames>=5)||s?.error;
    },null,{timeout:60000});
    await page.waitForTimeout(300);
    const status=await page.evaluate(()=>window.__cc155Status());
    if(status.error)throw Error('Model source render failed: '+status.error);
    assert.equal(status.loaded,true);
    assert.equal(status.figure,candidate.key);
    assert.equal(status.actualWebGL,true);
    assert.ok(status.webglDrawCalls>0&&status.triangles>0);
    assert.ok(status.frames>=5);
    assert.ok(status.skinnedMeshes>=1&&status.maxBones>=15);
    assert.equal(status.bakedGarments,true);
    assert.equal(status.ownerClothesApplied,false);
    assert.equal(status.original163BoneFallbackPreserved,true);
    assert.equal(status.releaseAuthorized,false);
    assert.equal(status.familyAlpha,'HOLD');
    assert.ok(status.modelMeshes>=1);
    assert.ok(status.boundsMeters.height>.5&&status.boundsMeters.height<4);
    assert.ok(status.boundsMeters.width>.1&&status.boundsMeters.width<4);
    assert.equal(errors.length,0,errors.join(' | '));
    assert.equal(failures.length,0,failures.join(' | '));
    assert.equal(requests.length,0,'P155 browsers must never connect to vendor');
    const bytes=await page.screenshot({fullPage:true,animations:'disabled'});
    const metadata=await sharp(bytes).metadata(),stats=await sharp(bytes).stats();
    assert.equal(metadata.width,width);
    assert.ok(bytes.length>8000);
    assert.ok(stats.channels.some(x=>x.stdev>9),'real render must have image contrast');
    const path=dir+'/screens/'+engine;
    await mkdir(path,{recursive:true});
    const file=candidate.key+'-'+view+'-'+width+'.png';
    await writeFile(path+'/'+file,bytes);
    evidence.push({engine,key:candidate.key,view,width,file,
     sha256:sha(bytes),size:bytes.length,
     screenshotHeight:metadata.height,
     actualOriginalSourceGLB:true,
     realWebGL:true,skinnedMeshes:status.skinnedMeshes,
     skinBones:status.maxBones,triangles:status.triangles,
     drawCalls:status.webglDrawCalls,frameCount:status.frames,
     noThirdPartyBrowserRequests:requests.length===0,
     originalPhotographedWardrobePreserved:true,
     sourceBuiltInGarment:true,independentHumanRealismApproved:false});
   }catch(e){problems.push({key:candidate.key,view,width,error:String(e),
      pageErrors:errors,failedRequests:failures,thirdPartyRequests:requests});
    throw e;
   }finally{await page.close();}
  }
  await context.close();
 }
 assert.equal(evidence.length,24);
 for(const width of widths)for(const candidate of CANDIDATES155){
  const one=evidence.find(x=>x.width===width&&x.key===candidate.key&&x.view==='front');
  const two=evidence.find(x=>x.width===width&&x.key===candidate.key&&x.view==='back');
  assert.ok(one&&two&&one.sha256!==two.sha256,
   'P155 front/back original geometry must render distinctly');
 }
 const outcome={
  priority:155,engine,realGLBSourceDownloadHashVerified:true,
  totalScreenshots:evidence.length,
  actualModels:CANDIDATES155.map(x=>x.key),
  mobileCSSViewportWidths:widths,
  originalSourceCandidateBytes:info.map(x=>({key:x.key,sha256:x.sha256,
   originalLicense:x.originalLicense,skins:x.skins,triangles:x.triangleCount,
   textures:x.textureCount,sourceBakedGarments:x.sourceHasBuiltInClothing})),
  sourceOriginalLicenseNoticeRetained:true,
  noExternalBrowserNetwork:true,
  realWebGLScreenshotEvidence:true,
  originalWardrobePhotographedGarmentCompatibility:false,
  actualOwnerGarmentDressFittingProven:false,
  visualHumanRealismAccepted:false,releaseAuthorized:false,
  familyAlpha:'HOLD',problems,evidence
 };
 await mkdir(dir+'/audit',{recursive:true});
 await writeFile(dir+'/audit/'+engine+'-acceptance.json',JSON.stringify(outcome,null,2)+'\n');
 console.log('P155_REAL_LICENSED_HUMANOID_GLTF_VISUAL '+JSON.stringify({
  engine,realSourceModels:2,actualScreenshots:evidence.length,
  realWebGLViews:evidence.length,retainedOwnerPhotoOutfit:true,
  originalMITLegalEvidence:true,sourceHasBakedClothes:true,
  canReplaceWardrobeModel:false,familyAlpha:'HOLD'}));
}finally{
 await browser?.close();
 await new Promise(ok=>server.close(ok));
 if(problems.length){
  await mkdir(dir+'/audit',{recursive:true});
  await writeFile(dir+'/audit/'+engine+'-failure.json',JSON.stringify(problems,null,2)+'\n');
 }
}
